function s = genHeader(fname, desc)
s = sprintf([ ...
"function [icRefA, icRefB, icRefC] = %s(vA,vB,vC,iLA,iLB,iLC,Vdc,VdcRef,Ts)\n" ...
"%%%s %s\n" ...
"%%   Paste this whole file's contents into a Simulink MATLAB Function\n" ...
"%%   block with inputs (vA,vB,vC,iLA,iLB,iLC,Vdc,VdcRef,Ts) and outputs\n" ...
"%%   (icRefA,icRefB,icRefC). Auto-generated by exportControllerCode.m --\n" ...
"%%   trained weights are embedded as literals, no file loading needed.\n"], ...
fname, upper(fname), desc);
end
